<?php $title='Berita';include 'includes/header.php';$id=(int)($_GET['id']??0);?><div class="container">
<?php if($id&&($b=row('SELECT b.*,k.nama kat FROM berita b JOIN kategori_berita k ON k.id=b.kategori_id WHERE b.id=?',[$id]))):?><h2 class="judul"><?=e($b['judul'])?></h2><p class="text-muted"><span class="badge bg-success"><?=e($b['kat'])?></span> <?=e($b['tanggal'])?> · <?=e($b['penulis'])?></p><?php if($b['foto']):?><img class="img-fluid rounded mb-3" src="assets/uploads/<?=e($b['foto'])?>"><?php endif;?><div class="card-desa bg-white p-4"><?=nl2br(e($b['isi']))?></div><a href="berita.php" class="btn btn-hijau mt-3">Kembali</a>
<?php else:?><h2 class="judul">Berita Desa</h2><form class="mb-3"><select name="k" class="form-select w-auto" onchange="this.form.submit()"><option value="">Semua Kategori</option><?php foreach(rows('SELECT * FROM kategori_berita') as $k):?><option value="<?=$k['id']?>" <?=(($_GET['k']??'')==$k['id'])?'selected':''?>><?=e($k['nama'])?></option><?php endforeach;?></select></form><div class="row g-3"><?php $k=(int)($_GET['k']??0);foreach(rows('SELECT b.*,k.nama kat FROM berita b JOIN kategori_berita k ON k.id=b.kategori_id WHERE (?=0 OR b.kategori_id=?) ORDER BY tanggal DESC,id DESC',[$k,$k]) as $b):?><div class="col-md-4"><a class="text-decoration-none text-dark" href="berita.php?id=<?=$b['id']?>"><div class="card-desa bg-white"><?php if($b['foto']):?><img class="thumb" src="assets/uploads/<?=e($b['foto'])?>"><?php else:?><div class="thumb"></div><?php endif;?><div class="p-3"><span class="badge bg-success"><?=e($b['kat'])?></span> <?=$b['headline']?'<span class="badge bg-warning">Headline</span>':''?><h6 class="mt-2"><?=e($b['judul'])?></h6><p class="small text-muted"><?=e($b['ringkasan'])?></p><small><?=e($b['tanggal'])?> · <?=e($b['penulis'])?></small></div></div></a></div><?php endforeach;?></div><?php endif;?></div>
<?php include 'includes/footer.php';?>
